<template>
  <div class="app-page">
    <header class="app-page-head"><div><span class="eyebrow">Infrastructure</span><h1 class="page-title">Nœuds</h1><p class="page-intro">Explorez les machines par rôle, version ou état sans charger une visualisation exhaustive.</p></div><UiButton variant="secondary" icon="refresh" :loading="loading" @click="loadNetwork(true)">Rafraîchir</UiButton></header>
    <section class="metric-grid"><MetricCard label="Nœuds recensés" :value="peers.length" detail="registre orchestrateur" icon="nodes" tone="ink"/><MetricCard label="Installations à jour" :value="currentCount" detail="version connue" icon="check" tone="mint"/><MetricCard label="Mises à jour requises" :value="outdatedCount" detail="version ou build" icon="download" :tone="outdatedCount ? 'amber' : 'mint'"/><MetricCard label="Rôles distincts" :value="roleGroups.length" detail="capacités annoncées" icon="processor" tone="violet"/></section>
    <UiCard>
      <template #header><div class="nodes-toolbar"><div class="nodes-search"><UiIcon name="search"/><input v-model.trim="search" type="search" placeholder="Rechercher un identifiant, rôle ou version" aria-label="Rechercher un nœud"></div><select v-model="role" class="select" aria-label="Filtrer par rôle"><option value="all">Tous les rôles</option><option v-for="group in roleGroups" :key="group.role" :value="group.role">{{ group.role }} ({{ group.count }})</option></select><select v-model="versionState" class="select" aria-label="Filtrer par version"><option value="all">Toutes les versions</option><option value="current">À jour</option><option value="outdated">Mise à jour requise</option></select></div></template>
      <UiNotice v-if="error" tone="warning">{{ error }}</UiNotice>
      <div v-if="loading && !peers.length" class="node-loading"><div v-for="n in 6" :key="n" class="skeleton"></div></div>
      <UiEmptyState v-else-if="!filtered.length" title="Aucun nœud correspondant" description="Modifiez les filtres ou attendez la prochaine publication de télémétrie." icon="nodes"/>
      <div v-else class="table-wrap"><table class="data-table nodes-table"><thead><tr><th>Nœud</th><th>Rôle(s)</th><th>Version</th><th>Canal</th><th>État logiciel</th></tr></thead><tbody><tr v-for="peer in visiblePeers" :key="peerId(peer)"><td><div class="node-identity"><span><UiIcon :name="peerId(peer) === 'orchestrator-1' ? 'layers' : 'processor'"/></span><div><strong>{{ peerId(peer) }}</strong><small>{{ peer.last_seen_utc || peer.lastSeenUtc ? `Vu ${formatDate(String(peer.last_seen_utc || peer.lastSeenUtc))}` : 'Télémétrie publiée' }}</small></div></div></td><td><div class="role-chips"><span v-for="peerRole in peerRoles(peer)" :key="peerRole">{{ peerRole }}</span></div></td><td class="mono">{{ peer.app_version || 'Non renseignée' }}</td><td>{{ peer.release_channel || 'inconnu' }}</td><td><UiStatusBadge :status="String(peer.version_status || (peer.outdated ? 'outdated' : 'current'))"/></td></tr></tbody></table></div>
      <footer v-if="filtered.length > pageSize" class="nodes-pagination"><span>{{ start + 1 }}–{{ Math.min(start + pageSize, filtered.length) }} sur {{ filtered.length }}</span><div><UiButton variant="secondary" size="small" :disabled="page === 1" @click="page--">Précédente</UiButton><UiButton variant="secondary" size="small" :disabled="start + pageSize >= filtered.length" @click="page++">Suivante</UiButton></div></footer>
    </UiCard>
  </div>
</template>

<script setup lang="ts">
import { formatDate, peerId, peerRoles } from '~/utils/format';
definePageMeta({ layout: 'app', middleware: 'auth' });
const network = useNetwork(); const { peers, roleGroups, outdatedCount, currentCount, loading, error, loadNetwork } = network;
const search = ref(''); const role = ref('all'); const versionState = ref('all'); const page = ref(1); const pageSize = 25;
const filtered = computed(() => peers.value.filter(peer => { const query = search.value.toLowerCase(); const matchesQuery = !query || `${peerId(peer)} ${peerRoles(peer).join(' ')} ${peer.app_version || ''}`.toLowerCase().includes(query); const matchesRole = role.value === 'all' || peerRoles(peer).includes(role.value); const matchesVersion = versionState.value === 'all' || (versionState.value === 'outdated' ? peer.outdated : !peer.outdated); return matchesQuery && matchesRole && matchesVersion; }).sort((a,b) => peerId(a).localeCompare(peerId(b))));
const start = computed(() => (page.value - 1) * pageSize); const visiblePeers = computed(() => filtered.value.slice(start.value, start.value + pageSize));
watch([search, role, versionState], () => { page.value = 1; });
onMounted(() => loadNetwork().catch(() => undefined));
useSeoMeta({ title: 'Nœuds — Silicium' });
</script>

<style scoped>
.nodes-toolbar{display:flex;width:100%;gap:.6rem}.nodes-search{position:relative;min-width:230px;flex:1}.nodes-search svg{position:absolute;top:50%;left:.8rem;width:.9rem;transform:translateY(-50%);color:var(--ink-500)}.nodes-search input{width:100%;height:2.45rem;padding:0 .8rem 0 2.2rem;border:1px solid var(--border);border-radius:.65rem;background:var(--surface-soft);font-size:.7rem}.nodes-toolbar .select{width:auto;min-width:155px;min-height:2.45rem;font-size:.66rem}.node-loading{display:grid;gap:.6rem;padding:1rem}.node-loading .skeleton{height:3.6rem}.nodes-table{min-width:820px}.node-identity{display:flex;min-width:200px;align-items:center;gap:.7rem}.node-identity>span{display:grid;width:2rem;height:2rem;place-items:center;border-radius:.55rem;background:var(--mint-100);color:var(--mint-700)}.node-identity svg{width:.88rem}.node-identity strong,.node-identity small{display:block}.node-identity strong{font-size:.7rem}.node-identity small{margin-top:.18rem;color:var(--ink-500);font-size:.56rem}.role-chips{display:flex;flex-wrap:wrap;gap:.25rem}.role-chips span{padding:.27rem .42rem;border-radius:.38rem;background:var(--ink-100);color:var(--ink-700);font-size:.55rem;text-transform:capitalize}.nodes-pagination{display:flex;align-items:center;justify-content:space-between;padding:.9rem 1.1rem;border-top:1px solid var(--border);color:var(--ink-500);font-size:.6rem}.nodes-pagination>div{display:flex;gap:.4rem}@media(max-width:700px){.nodes-toolbar{flex-wrap:wrap}.nodes-search{flex-basis:100%}.nodes-toolbar .select{min-width:130px;flex:1}}
</style>
